probe.proof:
by
  let t : Set ℤ := {x | ∃ b m : ℤ, (b : ℝ) ∈ Set.Icc (0 : ℝ) 0 ∧ x = b + m * 1}
  let s : Set ℤ := {a | (a : ℝ) ∈ Set.Icc (0 : ℝ) 0 ∧ (0 : ℤ) * a ∈ t}
  refine ⟨(fun u => ∃ n : ℕ, ∃ a d : ℤ, 0 < d ∧ u = {a + i * d | i : Fin n}), 1, 0, (fun _ => 0), (fun _ => 0), t, s, ?_⟩
  simp [t, s]
